mapper.select:
SELECT s.*, e.equip_name FROM prod_check_sheet s
LEFT JOIN base_equipment e ON e.equip_code = s.equip_code
WHERE s.equip_code = #{equipCode} AND s.prod_date = #{prodDate}

SELECT s.*, e.equip_name FROM prod_check_sheet s
LEFT JOIN base_equipment e ON e.equip_code = s.equip_code
WHERE s.sheet_id = #{sheetId}

mapper.update:
UPDATE quality_hardness_meas
   SET lot_no = #{lotNo}, worker_name = #{workerName}, meas_dt = #{measDt}, judgement = #{judgement},
       completed_dt = #{measDt}
 WHERE meas_id = #{measId}

mapper.select:
SELECT g.sheet_id AS sheetId, g.slot AS slot, g.user_id AS userId, g.sign_name AS signName, g.sign_dt AS signDt,
       (g.sign_img IS NOT NULL) AS hasImg
FROM prod_check_sign g
JOIN prod_check_sheet s ON s.sheet_id = g.sheet_id
WHERE s.prod_date BETWEEN #{from} AND #{to}
AND s.equip_code = #{equipCode}
